

namespace Stateless {
    
    /// <summary>
    ///   A class for looking up localized strings, etc.
    /// </summary>
    internal class StateRepresentationResources {
      
        /// <summary>
        ///   Looks up a localized string similar to Multiple permitted exit transitions are configured from state &apos;{1}&apos; for trigger &apos;{0}&apos;. Guard clauses must be mutually exclusive..
        /// </summary>
        internal static string MultipleTransitionsPermitted {
            get {
                return "Multiple permitted exit transitions are configured from state '{1}' for trigger '{0}'. Guard clauses must be mutually exclusive.";
            }
        }
    }
}
